import{_ as a,c as t,o as s,ag as n}from"./chunks/framework.CoPVQkzc.js";const u=JSON.parse('{"title":"Frequently Asked Questions","description":"Common questions and answers","frontmatter":{"title":"Frequently Asked Questions","description":"Common questions and answers"},"headers":[],"relativePath":"engine/faq.md","filePath":"engine/faq.md","lastUpdated":1788476353000}'),i={name:"engine/faq.md"};function o(r,e,d,h,l,c){return s(),t("div",null,e[0]||(e[0]=[n('<h1 id="frequently-asked-questions" tabindex="-1">Frequently Asked Questions <a class="header-anchor" href="#frequently-asked-questions" aria-label="Permalink to &quot;Frequently Asked Questions&quot;">​</a></h1><p>Common questions about using the Open Integration Engine.</p><h2 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h2><h3 id="what-is-the-relationship-between-oie-and-mirth-connecttm" tabindex="-1">What is the relationship between OIE and Mirth Connect™? <a class="header-anchor" href="#what-is-the-relationship-between-oie-and-mirth-connecttm" aria-label="Permalink to &quot;What is the relationship between OIE and Mirth Connect™?&quot;">​</a></h3><p>OIE (Open Integration Engine) is an open-source fork of Mirth Connect™, created after Mirth Connect™ shifted to a proprietary model. OIE continues the legacy of open healthcare integration under the Mozilla Public License 2.0.</p><h3 id="what-java-version-is-required" tabindex="-1">What Java version is required? <a class="header-anchor" href="#what-java-version-is-required" aria-label="Permalink to &quot;What Java version is required?&quot;">​</a></h3><p>Java 17 or later. The server launcher script automatically searches for a compatible runtime.</p><h3 id="what-databases-are-supported" tabindex="-1">What databases are supported? <a class="header-anchor" href="#what-databases-are-supported" aria-label="Permalink to &quot;What databases are supported?&quot;">​</a></h3><p>Apache Derby (embedded, default), PostgreSQL, MySQL, Oracle, and SQL Server. See <a href="./database_support.html">Database Support</a> for details.</p><h3 id="is-oie-free-to-use" tabindex="-1">Is OIE free to use? <a class="header-anchor" href="#is-oie-free-to-use" aria-label="Permalink to &quot;Is OIE free to use?&quot;">​</a></h3><p>Yes. OIE is licensed under the Mozilla Public License 2.0 (MPL 2.0), which allows free use, modification, and distribution.</p><h2 id="installation-and-setup" tabindex="-1">Installation and setup <a class="header-anchor" href="#installation-and-setup" aria-label="Permalink to &quot;Installation and setup&quot;">​</a></h2><h3 id="what-are-the-default-login-credentials" tabindex="-1">What are the default login credentials? <a class="header-anchor" href="#what-are-the-default-login-credentials" aria-label="Permalink to &quot;What are the default login credentials?&quot;">​</a></h3><p>Username: <code>admin</code>, Password: <code>admin</code>. Change this immediately after first login.</p><h3 id="what-are-the-default-ports" tabindex="-1">What are the default ports? <a class="header-anchor" href="#what-are-the-default-ports" aria-label="Permalink to &quot;What are the default ports?&quot;">​</a></h3><p>HTTP: <code>8080</code> (web server/launch page), HTTPS: <code>8443</code> (REST API/Administrator connections). The <a href="./web_administrator.html">Web Administrator</a>, when installed, is served on the same <code>8443</code> rather than a port of its own.</p><h3 id="do-i-have-to-use-the-desktop-administrator" tabindex="-1">Do I have to use the desktop Administrator? <a class="header-anchor" href="#do-i-have-to-use-the-desktop-administrator" aria-label="Permalink to &quot;Do I have to use the desktop Administrator?&quot;">​</a></h3><p>No. As of 4.6.0 the <a href="./web_administrator.html">Web Administrator</a> provides the same administration in a browser, installed as the Web Support extension. Both clients work against the same engine simultaneously, so there is no cutover. Scripted and headless administration goes through the <a href="./command_line_interface.html">CLI</a> or the <a href="./rest_api.html">REST API</a>.</p><h3 id="should-i-use-derby-in-production" tabindex="-1">Should I use Derby in production? <a class="header-anchor" href="#should-i-use-derby-in-production" aria-label="Permalink to &quot;Should I use Derby in production?&quot;">​</a></h3><p>No. Derby is suitable for development and evaluation. For production, use PostgreSQL, MySQL, Oracle, or SQL Server. See <a href="./database_support.html">Database Support</a>.</p><h3 id="how-do-i-change-the-database-after-installation" tabindex="-1">How do I change the database after installation? <a class="header-anchor" href="#how-do-i-change-the-database-after-installation" aria-label="Permalink to &quot;How do I change the database after installation?&quot;">​</a></h3><p>Edit <code>conf/mirth.properties</code> to update the <code>database</code>, <code>database.url</code>, <code>database.username</code>, and <code>database.password</code> properties. Restart the server. See <a href="./server_configuration.html">Server Configuration</a>.</p><h3 id="how-do-i-reset-the-admin-password" tabindex="-1">How do I reset the admin password? <a class="header-anchor" href="#how-do-i-reset-the-admin-password" aria-label="Permalink to &quot;How do I reset the admin password?&quot;">​</a></h3><p>Use the CLI: <code>user changepw admin &quot;newpassword&quot;</code>. If you cannot access the CLI, you can reset the password directly in the database.</p><h2 id="channels" tabindex="-1">Channels <a class="header-anchor" href="#channels" aria-label="Permalink to &quot;Channels&quot;">​</a></h2><h3 id="what-is-a-channel" tabindex="-1">What is a channel? <a class="header-anchor" href="#what-is-a-channel" aria-label="Permalink to &quot;What is a channel?&quot;">​</a></h3><p>A channel is the fundamental processing unit in OIE. It defines a complete message pipeline: how messages are received (source connector), how they are transformed, and where they are sent (destination connectors). See <a href="./channels_and_connectors.html">Channels and Connectors</a>.</p><h3 id="how-many-destinations-can-a-channel-have" tabindex="-1">How many destinations can a channel have? <a class="header-anchor" href="#how-many-destinations-can-a-channel-have" aria-label="Permalink to &quot;How many destinations can a channel have?&quot;">​</a></h3><p>There is no hard limit. A channel can have as many destinations as needed. Destinations process in order by default, but can be configured for parallel processing.</p><h3 id="what-is-the-difference-between-deploy-and-start" tabindex="-1">What is the difference between &quot;Deploy&quot; and &quot;Start&quot;? <a class="header-anchor" href="#what-is-the-difference-between-deploy-and-start" aria-label="Permalink to &quot;What is the difference between &quot;Deploy&quot; and &quot;Start&quot;?&quot;">​</a></h3><p><strong>Deploy</strong> loads the channel into the engine and starts it. <strong>Start</strong> resumes a channel that has been deployed but stopped or paused. A channel must be deployed before it can be started.</p><h3 id="how-do-i-pass-data-between-channels" tabindex="-1">How do I pass data between channels? <a class="header-anchor" href="#how-do-i-pass-data-between-channels" aria-label="Permalink to &quot;How do I pass data between channels?&quot;">​</a></h3><p>Use the <strong>Channel Writer</strong> (destination) and <strong>Channel Reader</strong> (source) connectors. You can also use the <code>VMRouter</code> class in JavaScript to route messages programmatically. The <code>globalMap</code> can share state, but for message passing, use the VM connectors.</p><h3 id="what-happens-when-a-destination-fails" tabindex="-1">What happens when a destination fails? <a class="header-anchor" href="#what-happens-when-a-destination-fails" aria-label="Permalink to &quot;What happens when a destination fails?&quot;">​</a></h3><p>Depending on the queue settings: the message is either marked as ERROR immediately (no queue), placed in the queue for retry (queue on failure), or was already queued (always queue). See the queue modes in <a href="./message_processing.html">Message Processing</a>.</p><h3 id="what-is-the-difference-between-the-source-filter-and-destination-filter" tabindex="-1">What is the difference between the source filter and destination filter? <a class="header-anchor" href="#what-is-the-difference-between-the-source-filter-and-destination-filter" aria-label="Permalink to &quot;What is the difference between the source filter and destination filter?&quot;">​</a></h3><p>The <strong>source filter</strong> runs once and determines if the message is processed at all. <strong>Destination filters</strong> run per-destination and determine if each individual destination processes the message.</p><h3 id="how-do-i-route-a-message-to-only-some-destinations" tabindex="-1">How do I route a message to only some destinations? <a class="header-anchor" href="#how-do-i-route-a-message-to-only-some-destinations" aria-label="Permalink to &quot;How do I route a message to only some destinations?&quot;">​</a></h3><p>Use destination filters on each destination, or use the <code>destinationSet</code> object in the source transformer to dynamically remove destinations:</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">destinationSet.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">remove</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">([</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Destination 2&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]);</span></span></code></pre></div><h2 id="transformers-and-scripts" tabindex="-1">Transformers and scripts <a class="header-anchor" href="#transformers-and-scripts" aria-label="Permalink to &quot;Transformers and scripts&quot;">​</a></h2><h3 id="what-is-the-difference-between-msg-and-tmp" tabindex="-1">What is the difference between <code>msg</code> and <code>tmp</code>? <a class="header-anchor" href="#what-is-the-difference-between-msg-and-tmp" aria-label="Permalink to &quot;What is the difference between `msg` and `tmp`?&quot;">​</a></h3><p><code>msg</code> is the parsed inbound message. <code>tmp</code> is a copy of the outbound message template (if one is defined). Both variables can be modified in JavaScript. If a template is defined, the engine uses <code>tmp</code> as the transformer output; if no template is defined, the engine uses <code>msg</code> as the output.</p><h3 id="what-javascript-engine-does-oie-use" tabindex="-1">What JavaScript engine does OIE use? <a class="header-anchor" href="#what-javascript-engine-does-oie-use" aria-label="Permalink to &quot;What JavaScript engine does OIE use?&quot;">​</a></h3><p>Mozilla Rhino, configured for ES6 by default (configurable via <code>rhino.languageversion</code> in <code>mirth.properties</code>).</p><h3 id="can-i-use-java-classes-in-my-javascript" tabindex="-1">Can I use Java classes in my JavaScript? <a class="header-anchor" href="#can-i-use-java-classes-in-my-javascript" aria-label="Permalink to &quot;Can I use Java classes in my JavaScript?&quot;">​</a></h3><p>Yes. Rhino runs on the JVM, so you can access any Java class directly:</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">var</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> uuid </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> java.util.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">UUID</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">randomUUID</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">().</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">toString</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span></code></pre></div><h3 id="what-is-e4x" tabindex="-1">What is E4X? <a class="header-anchor" href="#what-is-e4x" aria-label="Permalink to &quot;What is E4X?&quot;">​</a></h3><p>ECMAScript for XML, the syntax used to access and manipulate XML message content in transformers. Regardless of the original data type, messages are represented as XML internally:</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">var</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> value </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> msg[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;PID&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">][</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;PID.5&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">][</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;PID.5.1&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">].</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">toString</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span></code></pre></div><h3 id="how-do-i-add-a-segment-to-an-hl7-message" tabindex="-1">How do I add a segment to an HL7 message? <a class="header-anchor" href="#how-do-i-add-a-segment-to-an-hl7-message" aria-label="Permalink to &quot;How do I add a segment to an HL7 message?&quot;">​</a></h3><p>Use E4X to create and append segments in a JavaScript transformer step. See the <a href="./javascript_scripting_reference.html">JavaScript Scripting Reference</a> for detailed examples.</p><h3 id="how-do-i-delete-a-segment-from-an-hl7-message" tabindex="-1">How do I delete a segment from an HL7 message? <a class="header-anchor" href="#how-do-i-delete-a-segment-from-an-hl7-message" aria-label="Permalink to &quot;How do I delete a segment from an HL7 message?&quot;">​</a></h3><p>Use the <code>delete</code> keyword in E4X:</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">delete</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> tmp[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;ZZ1&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">];</span></span></code></pre></div><h2 id="data-types" tabindex="-1">Data types <a class="header-anchor" href="#data-types" aria-label="Permalink to &quot;Data types&quot;">​</a></h2><h3 id="what-data-types-are-supported" tabindex="-1">What data types are supported? <a class="header-anchor" href="#what-data-types-are-supported" aria-label="Permalink to &quot;What data types are supported?&quot;">​</a></h3><p>HL7 v2.x, HL7 v3.x, DICOM, XML, JSON, EDI/X12, NCPDP, Delimited Text, and Raw. See <a href="./data_types_and_formats.html">Data Types and Formats</a>.</p><h3 id="can-i-convert-between-data-types-in-a-single-channel" tabindex="-1">Can I convert between data types in a single channel? <a class="header-anchor" href="#can-i-convert-between-data-types-in-a-single-channel" aria-label="Permalink to &quot;Can I convert between data types in a single channel?&quot;">​</a></h3><p>Yes. Set different inbound/outbound data types on each connector. The engine handles serialization/deserialization at each boundary automatically.</p><h2 id="performance" tabindex="-1">Performance <a class="header-anchor" href="#performance" aria-label="Permalink to &quot;Performance&quot;">​</a></h2><h3 id="how-do-i-improve-channel-throughput" tabindex="-1">How do I improve channel throughput? <a class="header-anchor" href="#how-do-i-improve-channel-throughput" aria-label="Permalink to &quot;How do I improve channel throughput?&quot;">​</a></h3><ul><li>Set <strong>Message Storage</strong> to the minimum level you need (Production or Raw instead of Development)</li><li>Use <strong>Attachment Handlers</strong> for large messages to reduce memory usage</li><li>Enable <strong>source queuing</strong> if auto-generated ACKs are sufficient</li><li>Enable <strong>destination queuing</strong> if you don&#39;t need synchronous responses</li><li>Increase <strong>Max Processing Threads</strong> if message order doesn&#39;t matter</li><li>Increase <strong>Queue Threads</strong> if the downstream system can handle parallel connections</li><li>Uncheck <strong>Wait for previous destination</strong> unless ordering between destinations matters</li><li>Use <strong>Custom Metadata Columns</strong> to improve message search performance on frequently queried fields</li><li>Use <strong>Code Template Libraries</strong> to organize reusable code (vs. duplicating in every channel)</li></ul><h3 id="what-message-storage-mode-should-i-use" tabindex="-1">What message storage mode should I use? <a class="header-anchor" href="#what-message-storage-mode-should-i-use" aria-label="Permalink to &quot;What message storage mode should I use?&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Environment</th><th>Recommended Mode</th></tr></thead><tbody><tr><td>Development/Testing</td><td>Development (stores everything)</td></tr><tr><td>Production (need troubleshooting)</td><td>Production (raw + encoded)</td></tr><tr><td>Production (high throughput)</td><td>Raw or Metadata Only</td></tr><tr><td>Maximum performance</td><td>Disabled (no storage)</td></tr></tbody></table><h3 id="how-do-i-handle-large-messages" tabindex="-1">How do I handle large messages? <a class="header-anchor" href="#how-do-i-handle-large-messages" aria-label="Permalink to &quot;How do I handle large messages?&quot;">​</a></h3><p>Use an Attachment Handler to extract large content (images, documents) from the message body and store it separately. This reduces the in-memory message size and improves throughput.</p><h2 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h2><h3 id="how-do-i-replace-the-self-signed-tls-certificate" tabindex="-1">How do I replace the self-signed TLS certificate? <a class="header-anchor" href="#how-do-i-replace-the-self-signed-tls-certificate" aria-label="Permalink to &quot;How do I replace the self-signed TLS certificate?&quot;">​</a></h3><p>Use the <strong>TLS Manager</strong> web application at <code>https://&lt;host&gt;:8443/tls-manager/</code>, or manually import a CA-signed certificate into the keystore using Java&#39;s <code>keytool</code> utility.</p><h3 id="how-do-i-encrypt-the-database-password-in-mirth-properties" tabindex="-1">How do I encrypt the database password in mirth.properties? <a class="header-anchor" href="#how-do-i-encrypt-the-database-password-in-mirth-properties" aria-label="Permalink to &quot;How do I encrypt the database password in mirth.properties?&quot;">​</a></h3><p>The server can store encrypted values in the keystore. Refer to the server&#39;s encryption settings in <a href="./security_and_compliance.html">Security and Compliance</a>.</p><h3 id="is-oie-hipaa-compliant" tabindex="-1">Is OIE HIPAA compliant? <a class="header-anchor" href="#is-oie-hipaa-compliant" aria-label="Permalink to &quot;Is OIE HIPAA compliant?&quot;">​</a></h3><p>OIE provides the technical controls needed for HIPAA compliance (encryption, access control, audit logging), but compliance also requires organizational policies and procedures. See <a href="./security_and_compliance.html">Security and Compliance</a>.</p><h2 id="maintenance" tabindex="-1">Maintenance <a class="header-anchor" href="#maintenance" aria-label="Permalink to &quot;Maintenance&quot;">​</a></h2><h3 id="how-do-i-back-up-my-oie-instance" tabindex="-1">How do I back up my OIE instance? <a class="header-anchor" href="#how-do-i-back-up-my-oie-instance" aria-label="Permalink to &quot;How do I back up my OIE instance?&quot;">​</a></h3><ol><li>Export the server configuration: <code>exportcfg &quot;backup.xml&quot;</code> (via CLI)</li><li>Back up the <code>appdata/</code> directory (includes keystore and embedded database if using Derby)</li><li>Back up <code>conf/mirth.properties</code></li><li>If using an external database, back up that database separately</li></ol><h3 id="how-do-i-prevent-the-database-from-growing-too-large" tabindex="-1">How do I prevent the database from growing too large? <a class="header-anchor" href="#how-do-i-prevent-the-database-from-growing-too-large" aria-label="Permalink to &quot;How do I prevent the database from growing too large?&quot;">​</a></h3><p>Enable the <strong>Data Pruner</strong> in Settings and configure per-channel pruning policies. Set content pruning shorter than metadata pruning (e.g., prune content after 7 days, metadata after 30 days). See <a href="./data_pruning_and_maintenance.html">Data Pruning and Maintenance</a>.</p>',80)]))}const m=a(i,[["render",o]]);export{u as __pageData,m as default};
